const BY = Object.fromEntries(SEEDS.map(s=>[s.code,s]));
const CATS = [...new Set(SEEDS.map(s=>s.cat))].sort((a,b)=>a.localeCompare(b));

function natKey(c){const m=c.match(/^([A-Z]+)(\d*)$/i);return m?[m[1].toUpperCase(),m[2]?parseInt(m[2],10):-1]:[c.toUpperCase(),-1]}
function natCmp(a,b){const [pa,na]=natKey(a),[pb,nb]=natKey(b);return pa<pb?-1:pa>pb?1:na-nb}

const KEY="fhs-builder-v1";
let st={sel:{},custom:{},don:true,name:"",street:"",city:"",donor:"",demail:"",amt:"",similar:true,special:false,ordered:{},zone:"all"};
try{const s=localStorage.getItem(KEY);if(s)st=Object.assign(st,JSON.parse(s))}catch(e){}
if(!st.ordered||typeof st.ordered!=="object")st.ordered={};
function save(){try{localStorage.setItem(KEY,JSON.stringify(st))}catch(e){}}

const f={q:"",type:"all",life:"all",cat:"all",winter:false,deer:false,safe:false,picked:false,hideOrd:false};
const $=id=>ROOT.getElementById(id);
function twoTap(btn,fn){if(btn.dataset.arm){clearTimeout(btn._t);delete btn.dataset.arm;btn.classList.remove("arm");btn.textContent=btn.dataset.label;fn();return}btn.dataset.arm="1";btn.dataset.label=btn.textContent;btn.classList.add("arm");btn.textContent="Tap again to confirm";btn._t=setTimeout(()=>{delete btn.dataset.arm;btn.classList.remove("arm");btn.textContent=btn.dataset.label},4000)}

function chips(rowId,opts,key){
  const row=$(rowId);
  row.innerHTML="";
  opts.forEach(([v,label])=>{
    const b=document.createElement("button");
    b.className="chip";b.textContent=label;b.setAttribute("aria-pressed",f[key]===v);
    b.onclick=()=>{f[key]=v;if(key==="type"){f.cat="all";fillCats()}chips(rowId,opts,key);render()};
    row.appendChild(b);
  });
}
function toggles(){
  const row=$("flagRow");
  row.querySelectorAll(".chip").forEach(c=>c.remove());
  [["winter","Winter-sow friendly"],["deer","Deer resistant"],["safe","Hide pet/horse toxic"],["picked","Selected only"]].concat(Object.keys(st.ordered).length?[["hideOrd","Hide past orders"]]:[]).forEach(([k,label])=>{
    const b=document.createElement("button");
    b.className="chip";b.textContent=label;b.setAttribute("aria-pressed",f[k]);
    b.onclick=()=>{f[k]=!f[k];b.setAttribute("aria-pressed",f[k]);render()};
    row.appendChild(b);
  });
}
function fillCats(){
  const sel=$("cat");
  const cats=CATS.filter(c=>f.type==="all"||SEEDS.some(s=>s.cat===c&&s.type===f.type));
  sel.innerHTML=`<option value="all">All categories</option>`+cats.map(c=>`<option value="${c}">${c}</option>`).join("");
  sel.value=f.cat;
}
$("cat").onchange=e=>{f.cat=e.target.value;render()};
(function(){const z=$("zone");z.innerHTML=`<option value="all">Any zone</option>`+[3,4,5,6,7,8,9,10].map(n=>`<option value="${n}">Zone ${n}${n===6?" (Annandale 6b)":""}</option>`).join("");
 z.value=String(st.zone);if(z.value!==String(st.zone)){st.zone="all";z.value="all"}
 z.onchange=e=>{st.zone=e.target.value;save();render()};})();
$("q").oninput=e=>{f.q=e.target.value.trim().toLowerCase();render()};

const CHECK=`<svg viewBox="0 0 16 16" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M3 8.5l3 3 7-7"/></svg>`;
function esc(s){return String(s).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]))}

let shown=[];
function listText(items){
  const groups={};items.forEach(s=>{(groups[s.cat]=groups[s.cat]||[]).push(s)});
  let t=`FreeHeirloomSeeds.org seed list (as of 8/25/2026)\n${items.length} varieties. Request at FreeHeirloomSeeds.org; read their rules first.\n`;
  Object.keys(groups).sort((a,b)=>a.localeCompare(b)).forEach(cat=>{
    t+=`\n${cat.toUpperCase()}\n`;
    groups[cat].forEach(s=>{
      const bits=[s.days?`${s.days} days`:"",LIFE[s.life],s.L?"limited":"",s.O?"oversized":""].filter(Boolean).join(", ");
      t+=`${s.code} - ${s.name}${bits?` (${bits})`:""}\n`;
    });
  });
  return t;
}
function render(){
  const list=$("list");
  const items=SEEDS.filter(s=>{
    if(f.type!=="all"&&s.type!==f.type)return false;
    if(f.life!=="all"&&s.life!==f.life)return false;
    if(f.cat!=="all"&&s.cat!==f.cat)return false;
    if(f.winter&&!s.W)return false;
    if(f.deer&&!s.D)return false;
    if(f.safe&&s.T)return false;
    if(f.picked&&!st.sel[s.code])return false;
    if(f.hideOrd&&st.ordered[s.code])return false;
    if(st.zone!=="all"&&s.z){const z=+st.zone;if(z<s.z[0]||z>s.z[1])return false}
    if(f.q&&!(s.name.toLowerCase().includes(f.q)||s.code.toLowerCase().includes(f.q)||s.cat.toLowerCase().includes(f.q)))return false;
    return true;
  });
  shown=items;
  $("count").textContent=`${items.length} of ${SEEDS.length} varieties`+(st.zone!=="all"?` · perennials hardy in zone ${st.zone}`:"");
  $("copyList").textContent=items.length===SEEDS.length?"Copy full list":`Copy these ${items.length}`;
  if(!items.length){list.innerHTML=`<div class="empty">No seeds match these filters. Clear a filter or change the search.</div>`;updateBar();return}
  const groups={};
  items.forEach(s=>{(groups[s.cat]=groups[s.cat]||[]).push(s)});
  let html="";
  Object.keys(groups).sort((a,b)=>a.localeCompare(b)).forEach(cat=>{
    const g=groups[cat];
    html+=`<div class="group"><h2>${esc(cat)}<small>${g.length}</small></h2>`+(ABOUT[cat]?`<details class="about"><summary>About ${esc(cat.toLowerCase())}</summary><p>${esc(ABOUT[cat])}</p></details>`:"");
    g.forEach(s=>{
      const v=st.sel[s.code];
      const cls=itemCls(s.code);
      const meta=[s.days?`${s.days} days`:"",s.seeds?`${s.seeds} seeds`:"",TYPES[s.type],LIFE[s.life]].filter(Boolean).join(", ");
      let badges=st.ordered[s.code]?`<span class="b ord">Ordered before</span>`:"";
      if(s.z)badges+=`<span class="b">Zones ${s.z[0]}-${s.z[1]}</span>`;
      if(s.O)badges+=`<span class="b ovr">Oversized</span>`;
      if(s.L)badges+=`<span class="b lim">Limited</span>`;
      if(s.W)badges+=`<span class="b">Winter-sow</span>`;
      if(s.D)badges+=`<span class="b">Deer resistant</span>`;
      if(s.T)badges+=`<span class="b tox">Toxic to pets/horses</span>`;
      const photo=s.type==="F"?`<a class="photo" target="_blank" rel="noopener" href="https://www.google.com/search?tbm=isch&q=${encodeURIComponent(s.name+" "+s.cat+" flower")}">Photos</a>`:"";
      html+=`<div class="${cls}" data-code="${s.code}">
        <button class="check" data-act="toggle" aria-label="Request ${esc(s.name)}" aria-pressed="${!!v&&v!=='sub'}">${CHECK}</button>
        <div data-act="toggle"><div><span class="code">${s.code}</span><span class="name">${esc(s.name)}</span></div>
          <div class="meta">${esc(meta)}</div>
          ${s.note?`<div class="note">${esc(s.note)}</div>`:""}
          <div class="badges">${badges}</div>
          ${DESC[s.code]?`<details class="vd"><summary>Details</summary><p>${esc(DESC[s.code])}</p></details>`:""}</div>
        <div class="side"><button class="subbtn" data-act="sub">${v==="sub"?"Sub ✓":"Sub"}</button>${photo}</div>
      </div>`;
    });
    html+=`</div>`;
  });
  list.innerHTML=html;
  updateBar();
}
function itemCls(c){const v=st.sel[c];return (v==="sub"?"item subbed":v?"item on":"item")+(st.ordered[c]?" ordered":"")}
const NAMES=SEEDS.map(s=>[s.name.toLowerCase().replace(/\s*\(.*?\)\s*/g," ").replace(/[^a-z0-9' ]+/g," ").replace(/\s+/g," ").trim(),s.code]).sort((a,b)=>b[0].length-a[0].length);
function parseOrdered(text){
  const found=new Set();
  // codes: with digits match any case; codes without digits (e.g. ANG, BF) only in caps
  (text.match(/\b[A-Za-z]{1,6}\d*\b/g)||[]).forEach(t=>{
    const u=t.toUpperCase();
    if(!BY[u])return;
    if(/\d/.test(u)||t===u)found.add(u);
  });
  // names: lines whose text (minus codes, bullets, counts) is a seed name, or "Name - Category"
  const missed=[];
  text.split(/\n|;/).forEach(line=>{
    const raw=line.trim();if(!raw||/[@$]/.test(raw))return;
    const hadCode=(raw.match(/\b[A-Za-z]{1,6}\d+\b/g)||[]).some(t=>BY[t.toUpperCase()]);
    const clean=raw.toLowerCase().replace(/\(.*?\)/g," ").replace(/\b[a-z]{1,6}\d+\b/g," ").replace(/[^a-z0-9' ]+/g," ").replace(/\s+/g," ").trim();
    if(!clean)return;
    const hit=NAMES.filter(([n])=>n.length>=4&&(clean===n||clean.startsWith(n+" ")||clean.endsWith(" "+n)));
    if(hit.length===1)found.add(hit[0][1]);
    else if(hit.length>1){const exact=hit.find(([n])=>n===clean);if(exact)found.add(exact[1]);else if(!hadCode)missed.push(raw)}
    else if(!hadCode&&clean.split(" ").length<=6&&!/^(to|subject|from|seed request|special request|subs?)\b/.test(clean))missed.push(raw);
  });
  return {codes:[...found].sort(natCmp),missed};
}
function applyOrdered(replace){
  const {codes,missed}=parseOrdered($("ordText").value);
  if(!codes.length){$("ordRes").innerHTML=`No seed codes or names found in that text.`;return}
  if(replace)st.ordered={};
  let added=0;codes.forEach(c=>{if(!st.ordered[c]){st.ordered[c]=true;added++}});
  save();render();
  const tot=Object.keys(st.ordered).length;
  $("ordRes").innerHTML=`Matched ${codes.length}: <b>${codes.join(" ")}</b>. ${replace?"":`${added} new. `}${tot} tagged as ordered before.`+
    (missed.length?`<div class="miss">Couldn't match: ${missed.slice(0,8).map(esc).join(" · ")}${missed.length>8?` (+${missed.length-8} more)`:""}</div>`:"");
  $("ordText").value="";
}
function ordLabel(){const n=Object.keys(st.ordered).length;$("ordBtn").textContent=n?`Past orders (${n})`:"Past orders";toggles()}
$("ordBtn").onclick=()=>{const p=$("ordPanel");p.hidden=!p.hidden;$("ordBtn").setAttribute("aria-expanded",!p.hidden);if(!p.hidden)$("ordText").focus()};
$("ordAdd").onclick=()=>{applyOrdered(false);ordLabel()};
$("ordReplace").onclick=()=>{applyOrdered(true);ordLabel()};
$("ordClear").onclick=e=>twoTap(e.currentTarget,()=>{st.ordered={};save();render();ordLabel();$("ordRes").textContent="Ordered list cleared."});
$("list").addEventListener("click",e=>{
  if(e.target.closest("details"))return;
  const act=e.target.closest("[data-act]");if(!act)return;
  const item=e.target.closest(".item");const code=item.dataset.code;
  const cur=st.sel[code];
  if(act.dataset.act==="sub"){ if(cur==="sub")delete st.sel[code]; else st.sel[code]="sub"; }
  else { if(cur===true)delete st.sel[code]; else st.sel[code]=true; }
  save();
  const v=st.sel[code];
  item.className=itemCls(code);
  item.querySelector(".subbtn").textContent=v==="sub"?"Sub ✓":"Sub";
  item.querySelector(".check").setAttribute("aria-pressed",v===true);
  if(f.picked&&!v)render();
  updateBar();
});

function lists(){
  const main=[],subs=[];
  Object.entries(st.sel).forEach(([c,v])=>(v==="sub"?subs:main).push(c));
  Object.entries(st.custom).forEach(([c,v])=>(v.sub?subs:main).push(c));
  main.sort(natCmp);subs.sort(natCmp);
  return {main,subs};
}
function lines(codes){const out=[];for(let i=0;i<codes.length;i+=10)out.push(codes.slice(i,i+10).join(" "));return out}
function updateBar(){
  const {main,subs}=lists();
  $("barSum").textContent=main.length||subs.length?`${main.length} requested${subs.length?`, ${subs.length} substitute${subs.length>1?"s":""}`:""}`:"Nothing selected yet";
  $("tabCount").textContent=main.length?`(${main.length})`:"";
}
const TO="FreeHeirloomSeeds@gmail.com";
function subjFor(){return st.don?"Seed Request":"No Donation"}
function amtNum(){const n=parseFloat(String(st.amt).replace(/[^0-9.]/g,""));return isNaN(n)?0:n}
function packCap(a){if(a<12)return 8;if(a<20)return null;return 30+Math.floor((a-20)/10)*15}
function buildMail(){
  const {main,subs}=lists();
  const parts=[];
  if(st.don){
    const a=amtNum();
    const d=[st.donor.trim(),st.demail.trim(),a?`$${a%1?a.toFixed(2):a} donation`:""].filter(Boolean).join("   ");
    if(d)parts.push(d);
  }
  const addr=[st.name,st.street,st.city].map(x=>x.trim()).filter(Boolean);
  if(addr.length)parts.push(addr.join("\n"));
  if(main.length){
    const L=lines(main);
    if(st.don&&st.special)L[0]="special request\n"+L[0];
    parts.push(L.join("\n"));
  }
  if(subs.length){
    const L=lines(subs);
    if(st.don){L[0]="subs - "+L[0];if(st.similar)L[L.length-1]+=", or any similar varieties are fine";}
    parts.push(L.join("\n"));
  }
  if(!st.don&&st.similar)parts.push("Anything similar is fine.");
  return {subj:subjFor(),body:parts.join("\n\n"),main,subs};
}
function renderMail(){
  $("donYes").setAttribute("aria-pressed",st.don);$("donNo").setAttribute("aria-pressed",!st.don);
  $("fName").value=st.name;$("fStreet").value=st.street;$("fCity").value=st.city;
  $("fDonor").value=st.donor;$("fDEmail").value=st.demail;$("fAmt").value=st.amt;
  $("fSimilar").checked=st.similar;$("fSpecial").checked=st.special;
  $("donorBox").hidden=!st.don;$("fSpecial").parentElement.hidden=!st.don;
  refreshMail();
}
function refreshMail(){
  const m=buildMail();
  $("preview").textContent=(`To: ${TO}\nSubject: ${m.subj}\n\n`)+(m.body||"Pick seeds on the Seeds tab and they'll appear here.");
  $("mailto").href=`mailto:${TO}?subject=${encodeURIComponent(m.subj)}&body=${encodeURIComponent(m.body)}`;
  // picked chips
  const all=[...m.main.map(c=>[c,false]),...m.subs.map(c=>[c,true])];
  $("picked").innerHTML=all.length?all.map(([c,s])=>{const n=BY[c]?BY[c].name:"custom code";return `<span class="pk${s?" s":""}" title="${esc(n)}"><b class="code" style="border:0;padding:0;margin:0">${c}</b> ${esc(n)}${s?" (sub)":""}<button aria-label="Remove ${c}" data-rm="${c}">×</button></span>`}).join(""):`<span class="small">Nothing yet.</span>`;
  // warnings
  const w=[];
  const reg=m.main.filter(c=>!(BY[c]&&BY[c].O)&&!(st.custom[c]&&st.custom[c].O));
  const ovr=m.main.filter(c=>(BY[c]&&BY[c].O));
  if(!m.main.length)w.push(["Select at least one seed to build your request.",0]);
  if(!st.don){
    if(m.main.length!==5)w.push([`No-donation requests list exactly 5 first choices. You have ${m.main.length}.`,0]);
    if(m.subs.length!==10)w.push([`No-donation requests list 10 backup selections (tap Sub). You have ${m.subs.length}.`,0]);
    if(ovr.length)w.push([`${ovr.join(", ")} ${ovr.length>1?"are":"is"} on the oversized list, which is rarely filled without a donation.`,0]);
    w.push(["No-donation requests are limited to one per address per year.",1]);
    const g={};m.main.forEach(c=>{const s=BY[c];if(s&&s.xg){(g[s.xg]=g[s.xg]||[]).push(c)}});
    Object.entries(g).filter(([k,v])=>v.length>1).forEach(([k,v])=>w.push([`${v.join(", ")} will cross-pollinate (${k}). The site asks no-donation requests to pick only one per family, or you may get only 3 packs.`,0]));
  }else{
    const a=amtNum(),cap=packCap(a);
    if(!a)w.push(["Enter your donation amount; the site asks you to include it.",0]);
    else if(a<12){
      if(m.main.length>8)w.push([`Donations under $12 get a standard envelope with at most 8 packs. You've picked ${m.main.length}.`,0]);
      if(ovr.length)w.push([`Donations under $12 can't include oversized seeds (${ovr.join(", ")}).`,0]);
      w.push(["Donations under $12 aren't trackable.",1]);
    }else if(cap===null){
      w.push(["The suggested minimum is $20 (up to 30 packs). Between $12 and $20 is trackable but below the suggested minimum.",0]);
    }else if(m.main.length>cap&&!st.special){
      w.push([`$${a} covers up to ${cap} packs; you've picked ${m.main.length}. Add $10 per extra 15 packs, trim the list, or mark it as a special request.`,0]);
    }
    if(!st.donor.trim()||!st.demail.trim())w.push(["Add the name and email you used for the donation so they can match it.",0]);
  }
  const corn=m.main.filter(c=>BY[c]&&BY[c].cat==="Corn");
  if(corn.length>1)w.push([`Only one corn pack is allowed per address per year, regardless of donation (${corn.join(", ")}).`,0]);
  {const g={};m.main.forEach(c=>{const s=BY[c];if(s&&s.xg){(g[s.xg]=g[s.xg]||[]).push(c)}});
   const capNow=packCap(amtNum());
   if(st.don&&(st.special||(capNow&&m.main.length>capNow)))Object.entries(g).filter(([k,v])=>v.length>1).forEach(([k,v])=>w.push([`${v.join(", ")} cross-pollinate (${k}). The site says it's unlikely to send several crossing varieties on large or special requests.`,0]));}
  const again=m.main.concat(m.subs).filter(c=>st.ordered[c]);
  if(again.length)w.push([`You've requested these before (Past orders): ${again.join(", ")}.`,0]);
  const tox=m.main.concat(m.subs).filter(c=>BY[c]&&BY[c].T);
  if(tox.length)w.push([`Toxic to dogs or horses: ${tox.join(", ")}. Plant away from paddocks and dog runs.`,0]);
  if(!m.subs.length&&m.main.length)w.push(["The rules require substitutes; the list changes often and they won't email to ask.",0]);
  if(!st.name.trim()||!st.street.trim()||!st.city.trim())w.push(["Fill in the recipient name and full mailing address, including ZIP.",0]);
  if(!w.length)w.push(["Looks ready. Refresh the site's list before sending to confirm everything is still available.",1]);
  $("warns").innerHTML=w.map(([t,ok])=>`<li class="${ok?"ok":""}">${esc(t)}</li>`).join("");
  updateBar();
}
$("picked").addEventListener("click",e=>{const c=e.target.dataset.rm;if(!c)return;delete st.sel[c];delete st.custom[c];save();refreshMail()});
[["fName","name"],["fStreet","street"],["fCity","city"],["fDonor","donor"],["fDEmail","demail"],["fAmt","amt"]].forEach(([id,k])=>{$(id).oninput=e=>{st[k]=e.target.value;save();refreshMail()}});
